-- Proposta de esquema PostgreSQL para revisão; NÃO é executada automaticamente.
-- A API pública não recebe permissões neste esquema. A aplicação ainda precisa
-- de autenticação, políticas por usuário e migração do repositório para Postgres.
BEGIN;
CREATE SCHEMA IF NOT EXISTS ada;
REVOKE ALL ON SCHEMA ada FROM PUBLIC;
CREATE TABLE IF NOT EXISTS ada.agents (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL, active_version INTEGER NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ada.agent_versions (agent_id BIGINT NOT NULL REFERENCES ada.agents(id), number INTEGER NOT NULL, spec_json TEXT NOT NULL, reason TEXT NOT NULL, origin TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(agent_id,number));
CREATE TABLE IF NOT EXISTS ada.conversations (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, agent_id BIGINT NOT NULL REFERENCES ada.agents(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ada.messages (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, conversation_id BIGINT NOT NULL REFERENCES ada.conversations(id), role TEXT NOT NULL, content TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ada.runs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, agent_id BIGINT NOT NULL REFERENCES ada.agents(id), conversation_id BIGINT NOT NULL REFERENCES ada.conversations(id), status TEXT NOT NULL, steps INTEGER NOT NULL DEFAULT 0, tokens_in INTEGER NOT NULL DEFAULT 0, tokens_out INTEGER NOT NULL DEFAULT 0, cost_estimate DOUBLE PRECISION, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ada.run_events (run_id BIGINT NOT NULL REFERENCES ada.runs(id), seq INTEGER NOT NULL, type TEXT NOT NULL, payload_json TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(run_id,seq));
CREATE TABLE IF NOT EXISTS ada.approvals (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, run_id BIGINT NOT NULL REFERENCES ada.runs(id), tool TEXT NOT NULL, payload_json TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), decided_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS ada.documents (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, agent_id BIGINT NOT NULL REFERENCES ada.agents(id), name TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ada.chunks (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, document_id BIGINT NOT NULL REFERENCES ada.documents(id) ON DELETE CASCADE, agent_id BIGINT NOT NULL REFERENCES ada.agents(id), position INTEGER NOT NULL, content TEXT NOT NULL);
CREATE OR REPLACE FUNCTION ada.prevent_version_update() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'agent versions are immutable'; END; $$;
DROP TRIGGER IF EXISTS immutable_versions ON ada.agent_versions;
CREATE TRIGGER immutable_versions BEFORE UPDATE ON ada.agent_versions FOR EACH ROW EXECUTE FUNCTION ada.prevent_version_update();
REVOKE ALL ON ALL TABLES IN SCHEMA ada FROM PUBLIC;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA ada FROM PUBLIC;
COMMIT;
